    transition: all 0.3s ease;
}

.deal-card:hover {
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.1);
    transform: translateY(-4px);
}

.deal-header {
    background: linear-gradient(135deg, var(--accent-color) 0%, #c9935a 100%);
