    padding: 1.5rem;
    text-align: center;
}

.deal-discount {
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 0.25rem;
}

.deal-label {
    font-size: 0.9rem;
    opacity: 0.9;
}

.deal-body {
    padding: 1.5rem;
    text-align: center;
}

.deal-title {
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
