}

.deal-card .btn {
    width: 100%;
}

/* Editorial Content */
.editorial {
    padding: 4rem 0;
    background: #fff;
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.3s ease;
    cursor: pointer;
}

.editorial-card:hover {
    box-shadow: 0 12px 24px rgba(0, 0, 0, 0.1);
}

.editorial-image {
