    text-transform: uppercase;
    margin-bottom: 0.75rem;
}

.editorial-title {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 0.75rem;
    color: var(--primary-color);
}

.editorial-excerpt {
    color: #666;
    margin-bottom: 1rem;
    font-size: 0.95rem;
}

.read-more {
    color: var(--accent-color);
    font-weight: 600;
    text-decoration: none;
    transition: all 0.3s ease;
    display: inline-flex;
    align-items: center;
