}

.read-more:hover {
    gap: 0.75rem;
}

/* Newsletter Section */
.newsletter {
    padding: 3rem 0;
    background: var(--primary-color);
    color: white;
}

.newsletter-content {
    text-align: center;
}

.newsletter-content h2 {
    font-size: 2rem;
