        title: 'The Art of Minimalist Fashion',
        excerpt: 'Learn how to build a capsule wardrobe with timeless, versatile pieces.',
        emoji: '✨'
    },
    {
        id: 3,
        tag: 'Sustainability',
        title: 'Our Eco-Friendly Collections',
        excerpt: 'Explore our commitment to sustainable fashion and ethical production.',
        emoji: '🌿'
    }
];

// Cart
let cart = {
    items: [],
    get count() {
        return this.items.length;
    },
    addItem(product) {
        this.items.push(product);
        this.updateCartCount();
        this.showToast(`${product.name} added to cart!`);
    },
    updateCartCount() {
        const cartCount = document.querySelector('.cart-count');
        if (cartCount) {
            cartCount.textContent = this.count;
        }
    },
    showToast(message) {
        const toast = document.createElement('div');
        toast.className = 'toast';
        toast.textContent = message;
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 3000);
    }
};

// Render Functions
function renderProductCard(product) {
    const discount = Math.round(((product.originalPrice - product.price) / product.originalPrice) * 100);

    return `
        <div class="product-card">
            <div class="product-image">${product.emoji}</div>
            <div class="product-info">
                <div class="product-category">${product.category}</div>
                <h3 class="product-name">${product.name}</h3>
                <p class="product-description">${product.description}</p>
                <div class="product-price">
                    <span class="price-current">$${product.price}</span>
                    <span class="price-original">$${product.originalPrice}</span>
                    <span style="margin-left: auto; color: var(--accent-color); font-weight: 600;">-${discount}%</span>
                </div>
                <div class="product-actions">
                    <button class="btn-add-cart" onclick="addToCart(${product.id})">Add to Cart</button>
                    <button class="btn-favorite" title="Add to favorites">♡</button>
                </div>
            </div>
        </div>
    `;
}

function renderDealCard(deal) {
    return `
        <div class="deal-card">
            <div class="deal-header">
                <div class="deal-discount">${deal.discount}</div>
                <div class="deal-label">OFF</div>
            </div>
            <div class="deal-body">
                <h3 class="deal-title">${deal.title}</h3>
                <p class="deal-description">${deal.description}</p>
                <div class="deal-expiry">${deal.expiryDate}</div>
                <button class="btn btn-secondary" onclick="handleDealClick('${deal.title}')">Claim Now</button>
            </div>
        </div>
    `;
}

function renderEditorialCard(article) {
    return `
        <div class="editorial-card" onclick="handleArticleClick('${article.title}')">
            <div class="editorial-image">${article.emoji}</div>
            <div class="editorial-content">
                <span class="editorial-tag">${article.tag}</span>
                <h3 class="editorial-title">${article.title}</h3>
                <p class="editorial-excerpt">${article.excerpt}</p>
                <a href="#" class="read-more">Read More →</a>
            </div>
        </div>
    `;
}

// Initialize
function init() {
    renderFeaturedProducts();
    renderDeals();
    renderEditorial();
    setupEventListeners();
}

function renderFeaturedProducts() {
    const container = document.getElementById('featured-products');
    if (container) {
        container.innerHTML = featuredProducts.map(renderProductCard).join('');
    }
}

function renderDeals() {
    const container = document.getElementById('deals-grid');
    if (container) {
        container.innerHTML = deals.map(renderDealCard).join('');
    }
}

function renderEditorial() {
    const container = document.getElementById('editorial-grid');
    if (container) {
        container.innerHTML = editorialContent.map(renderEditorialCard).join('');
    }
}

// Event Handlers
function addToCart(productId) {
    const product = featuredProducts.find(p => p.id === productId);
    if (product) {
        cart.addItem(product);
    }
}

function handleDealClick(dealTitle) {
    cart.showToast(`"${dealTitle}" added to your cart!`);
}

function handleArticleClick(articleTitle) {
    cart.showToast(`Opening "${articleTitle}"...`);
}

function handleNewsletterSubmit(event) {
    event.preventDefault();
    const email = event.target.querySelector('.newsletter-input').value;
    cart.showToast(`Welcome aboard! Check your email at ${email}`);
    event.target.reset();
}

function scrollToFeatured() {
    const featured = document.getElementById('featured');
    if (featured) {
        featured.scrollIntoView({ behavior: 'smooth' });
    }
}

function setupEventListeners() {
    // Favorite button interactivity
    document.addEventListener('click', (e) => {
        if (e.target.classList.contains('btn-favorite')) {
            e.target.textContent = e.target.textContent === '♡' ? '♥' : '♡';
            e.target.style.color = e.target.textContent === '♥' ? 'var(--accent-color)' : '';
        }
    });
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', init);
